    private int hours;
    public Parking(String plate, int hours)
    {
        this.plate = plate;
        this.hours = hours;
    }
    @Override
    public double cost()
    {
        return hours * 3.0;
    }
    @Override
    public String toString()
    {
        return "Parking " + plate + ": " + hours + " hours, cost " + cost();
    }
}

public class InvoiceDemo
{
    public static void main(String[] args)
    {
        Vehicle car = new Car("CAR-7");
        Vehicle truck = new Truck("TRK-42", 900);
        car.drive(30);
        truck.drive(150);
        Invoice invoice = new Invoice();
        invoice.add(car);
        invoice.add(truck);
        invoice.add(new Parking("CAR-7", 4));
        invoice.printAll();
        System.out.println("Total: " + invoice.total());
    }
}

