public interface Sellable
{
    int price();

    default String priceText()
    {
        return price() + " dollars";
    }
}

public abstract class Ticket implements Sellable
{
    private String seat;
    public Ticket(String seat)
    {
        this.seat = seat;
    }
    public String getSeat()
    {
        return seat;
    }
    @Override
    public String toString()
    {
        return seat + ": " + priceText();
    }
}

public class AdultTicket extends Ticket
{
    public AdultTicket(String seat)
    {
        super(seat);
    }
    @Override
    public int price()
    {
        return 20;
    }
}

public class StudentTicket extends Ticket
{
    private String studentId;
    public StudentTicket(String seat,
            String studentId)
    {
        super(seat);
        this.studentId = studentId;
    }
    public String getStudentId()
    {
        return studentId;
    }
    @Override
    public int price()
    {
        return 15;
    }
    @Override
    public String toString()
    {
        return super.toString() + ", student " + studentId;
    }
}

public class Snack implements Sellable
{
    private String name;
    private int price;
    public Snack(String name, int price)
    {
        this.name = name;
        this.price = price;
    }
    @Override
    public int price()
    {
        return price;
    }
    @Override
    public String toString()
    {
        return name + ": " + priceText();
    }
}

public class OrderDemo
{
    public static void main(String[] args)
    {
        Order order = new Order();
        order.add(new AdultTicket("A3"));
        order.add(new StudentTicket("B12", "2001234"));
        order.add(new Snack("popcorn", 6));
        order.printAll();
        System.out.println("Total: " + order.total() + " dollars");
    }
}
